    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "नैवाकृतिः फलति नैव कुलं न शीलं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "विद्यापि नैव न च यत्नकृतापि सेवा ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "भाग्यानि पूर्वतपसा खलु संचितानि",
          "end": "line"
        },
        {
          "n": 4,
          "text": "",
          "end": "space"
        },
        {
          "n": 5,
          "text": "काले फलन्ति पुरुषस्य यथैव वृक्षाः ॥ ९६ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "वने रणे शत्रुजलाग्निमध्ये",
          "end": "line"
        },
        {
          "n": 2,
          "text": "महार्णवे पर्वतमस्तके वा ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "सुप्तं प्रमत्तं विषमस्थितं वा",
          "end": "line"
        },
        {
          "n": 4,
          "text": "रक्षन्ति पुण्यानि पुरा कृतानि ॥९७॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "या साधूंश्च खलान्करोति विदुषो मूर्खान्हितान्द्वेषिणः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "प्रत्यक्षं कुरुते परोक्षममृतं हालाहलं तत्क्षणात् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "तामाराधय सत्क्रियां भगवतीं भोक्तुं फलं वाञ्छितं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "",
          "end": "space"
        },
        {
          "n": 5,
          "text": "हे साधो व्यसनैर्गुणेषु विपुलेष्वास्थां वृथा मा कृथाः ॥ ९८ ॥",
          "end": "space"
        },
        {
          "n": 6,
          "text": "",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "गुणवदगुणवद्वा कुर्वता कार्यमादौ",
          "end": "line"
        },
        {
          "n": 2,
          "text": "परिणतिरवधार्या यत्नतः पण्डितेन ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "अतिरभसकृतानां कर्मणामाविपत्ते-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "र्भवति हृदयदाही शल्यतुल्यो विपाकः ॥ ९९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
